private static void requireDeliveryTransition(DeliveryWatermark appended, DeliveryWatermark after) {
    if (!appended.sessionId().equals(after.sessionId()) || appended.lastEventSeq() != after.lastEventSeq()) {
        throw new IllegalArgumentException("delivery event watermark transition is invalid");
    }
    boolean snapshotUnchanged = appended.snapshotRevision() == after.snapshotRevision()
            && appended.snapshotBaseEventSeq() == after.snapshotBaseEventSeq();
    boolean snapshotAdvanced = after.snapshotRevision() == increment(appended.snapshotRevision())
            && after.snapshotBaseEventSeq() >= appended.snapshotBaseEventSeq()
            && after.snapshotBaseEventSeq() <= after.lastEventSeq();
    if (!snapshotUnchanged && !snapshotAdvanced) {
        throw new IllegalArgumentException("snapshot watermark must remain or advance exactly once");
    }
    if (after.replayFloorSeq() < appended.replayFloorSeq()
            || after.replayFloorSeq() > after.snapshotBaseEventSeq()) {
        throw new IllegalArgumentException("replay floor must advance within snapshot coverage");
    }
}

private static void requireExpected(long actual, long expected, String name) {
    if (expected < 0 || actual != expected) {
        throw new IllegalStateException(name + " revision conflict: expected " + expected + ", current " + actual);
    }
}

private static void requireText(String value, String name) {
    if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
